mapper.select:
SELECT a.id, v.id AS vehicle_id, v.vin, a.stage_status, a.allocated_date, a.dealer_id, d.dealer_name, a.sales_status, a.remark3, a.confirmed_by, a.confirmed_at FROM t_vehicle v LEFT JOIN t_veh_allocation a ON a.vehicle_id = v.id AND a.deleted = 0 LEFT JOIN t_md_dealer d ON d.id = a.dealer_id AND d.deleted = 0 WHERE v.deleted = 0
AND v.vin LIKE CONCAT('%', #{query.vin}, '%')
AND a.dealer_id = #{query.dealerId}
AND v.lifecycle_stage = #{query.stageStatus}
AND a.stage_status = #{query.stageStatus}
AND a.id IS NOT NULL
ORDER BY v.id DESC
